import{_ as a,o as t,c as r,a3 as n}from"./chunks/framework.CWSmAuPU.js";const h=JSON.parse('{"title":"0015 需求变更后增量继续，而不是从零重做","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0015-incremental-continue.md","filePath":"reference/adr/0015-incremental-continue.md","lastUpdated":null}'),o={name:"reference/adr/0015-incremental-continue.md"};function i(c,e,l,d,s,u){return t(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="_0015-需求变更后增量继续-而不是从零重做" tabindex="-1">0015 需求变更后增量继续，而不是从零重做 <a class="header-anchor" href="#_0015-需求变更后增量继续-而不是从零重做" aria-label="Permalink to &quot;0015 需求变更后增量继续，而不是从零重做&quot;">​</a></h1><ul><li>状态：已采纳（细化 <a href="./0011-resume-after-completion">0011</a>：0011 决定&quot;可以继续&quot;，本条决定&quot;怎么继续&quot;）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>1.2 中 spec 改动或回答了需求方的问题后继续，是&quot;从方案设计重新开始&quot;：步骤 agent 拿到的提示与第一次相同，往往重新写一遍方案、重新审核全部代码，耗时接近第一次，还可能改掉已经验收过的部分。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li>从方案设计继续时，状态中记录 <code>incremental</code>：接着第几次尝试、原因、本次开始时的提交、上一次是否已写过代码。</li><li>各步骤的提示附加 <code>engine/prompts/incremental.md</code>：方案在原文末尾追加&quot;第 N 次尝试：需求变更&quot;一节，只设计变化的部分；实现只改需要改的；代码评审只看本次开始以来的改动；验证重点验变化的验收标准，并回归其余的；报告说明这是第几次。</li><li><code>--restart</code> 仍是完全从零开始，不参考上次的方案和代码。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><p>变更后的继续通常比第一次快很多。增量的前提是上次的方案和提交还在分支上；如果分支被重置过，应使用 <code>--restart</code>。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0015-incremental-continue.md">docs/adr/0015-incremental-continue.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0015-incremental-continue.md">在 GitHub 上编辑</a></p>',2)])])}const p=a(o,[["render",i]]);export{h as __pageData,p as default};
